create table if not exists public.products (
  id text primary key,
  title text not null,
  brand text not null default '',
  size text not null default '',
  condition text not null default '',
  price text not null default '',
  created_at timestamptz not null default now(),
  image text not null default '',
  vinted_url text not null default ''
);

alter table public.products enable row level security;

on conflict (id) do update set
 title=excluded.title, brand=excluded.brand, size=excluded.size,
 condition=excluded.condition, price=excluded.price, created_at=excluded.created_at,
 image=excluded.image, vinted_url=excluded.vinted_url;
